   153  otError UdpSocket::SendTo(Message &aMessage, const MessageInfo &aMessageInfo)
   154  {
   155      otError     error = OT_ERROR_NONE;
   156      MessageInfo messageInfoLocal;
   157
   158      VerifyOrExit((aMessageInfo.GetSockPort() == 0) || (GetSockName().mPort == aMessageInfo.GetSockPort()),
   159                   error = OT_ERROR_INVALID_ARGS);
   160
   161      messageInfoLocal = aMessageInfo;
   162
   163      if (messageInfoLocal.GetPeerAddr().IsUnspecified())
   164      {
   165          VerifyOrExit(!GetPeerName().GetAddress().IsUnspecified(), error = OT_ERROR_INVALID_ARGS);
   166
   167          messageInfoLocal.SetPeerAddr(GetPeerName().GetAddress());
   168      }
   169
   170      if (messageInfoLocal.mPeerPort == 0)
   171      {
   172          VerifyOrExit(GetPeerName().mPort != 0, error = OT_ERROR_INVALID_ARGS);
   173          messageInfoLocal.mPeerPort = GetPeerName().mPort;
   174      }
   175
   176      if (messageInfoLocal.GetSockAddr().IsUnspecified())
   177      {
   178          messageInfoLocal.SetSockAddr(GetSockName().GetAddress());
   179      }
   180
   181      if (!IsBound())
   182      {
   183          SuccessOrExit(error = Bind(GetSockName()));
   184      }
   185
   186      messageInfoLocal.SetSockPort(GetSockName().mPort);
   187
   188  #if OPENTHREAD_ENABLE_PLATFORM_UDP
   189      if (!IsMle(GetInstance(), mSockName.mPort) &&
   190          !(mSockName.mPort == ot::kCoapUdpPort && aMessage.GetSubType() == Message::kSubTypeJoinerEntrust))
   191      {
   192          SuccessOrExit(error = otPlatUdpSend(this, &aMessage, &messageInfoLocal));
   193      }
   194      else
   195  #endif
   196      {
   197          SuccessOrExit(error = Get<Udp>().SendDatagram(aMessage, messageInfoLocal, kProtoUdp));
   198      }
   199
   200  exit:
   201      return error;
   202  }
