   216  otError Udp::AddReceiver(UdpReceiver &aReceiver)
   217  {
   218      otError error = OT_ERROR_NONE;
   219
   220      for (UdpReceiver *cur = mReceivers; cur; cur = cur->GetNext())
   221      {
   222          if (cur == &aReceiver)
   223          {
   224              ExitNow(error = OT_ERROR_ALREADY);
   225          }
   226      }
   227
   228      aReceiver.SetNext(mReceivers);
   229      mReceivers = &aReceiver;
